/* RT-1 live audio provider fixtures. Written before the implementation.
 *
 * usage: live_audio_fixture <fixture_dir> <game_dir|-> [list | smoke | test...]
 *
 * <fixture_dir> holds a synthetic game tree (CDSound, several .HIS files) generated by
 * tests/test_live_audio.py; <game_dir> is the owner's install for the one
 * end-to-end test (or "-"). Output: one "TEST <name> PASS|FAIL|SKIP <detail>"
 * line per test; exit status is nonzero when any test fails. */

#include <math.h>
#include <pthread.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#include "action_sound.h"
#include "his_audio.h"
#include "live_audio.h"
#include "macos_audio.h"

/* ---- fixture assets (must match tests/test_live_audio.py) ------------- */
#define TONE_FRAMES 20000u   /* stereo 48000 Hz, square wave +-0.5 */
#define LONG_FRAMES 60000u   /* stereo 48000 Hz, square wave +-0.5 */
#define MONO_FRAMES 5000u    /* mono 22050 Hz 16-bit, square wave +-0.25 */

/* ---- tiny harness ------------------------------------------------------ */
typedef struct Ctx {
    const char *fixture_dir;
    const char *game_dir;
    int failed;
    int skipped;
    char detail[512];
} Ctx;

#define CHECK(ctx, cond, ...) \
    do { \
        if (!(cond) && !(ctx)->failed) { \
            (ctx)->failed = 1; \
            int n_ = snprintf((ctx)->detail, sizeof((ctx)->detail), \
                              "line %d: %s: ", __LINE__, #cond); \
            if (n_ > 0 && (size_t)n_ < sizeof((ctx)->detail)) \
                snprintf((ctx)->detail + n_, sizeof((ctx)->detail) - (size_t)n_, \
                         "" __VA_ARGS__); \
        } \
    } while (0)

static char g_log[128][256];
static int g_log_count;

static void log_sink(void *context, const char *message)
{
    (void)context;
    if (g_log_count < 128) {
        snprintf(g_log[g_log_count], sizeof(g_log[0]), "%s", message);
        ++g_log_count;
    }
}

static int log_contains(const char *needle)
{
    for (int i = 0; i < g_log_count; ++i)
        if (strstr(g_log[i], needle) != NULL) return 1;
    return 0;
}

/* ---- fake host --------------------------------------------------------- */
typedef struct FakeSlot {
    int active;
    int plays;
    int stops;
    int set_gains;
    float gain;
    float last_set_gain;
    uint64_t frames;
    uint32_t channels;
    uint32_t rate;
} FakeSlot;

typedef struct FakeEvent {
    char op;
    uint32_t slot;
} FakeEvent;

typedef struct FakeHost {
    FakeSlot slots[64];
    FakeEvent events[512];
    int event_count;
    int opens, closes, renders;
    MacAudioMode mode;
    uint32_t rate, channels;
    int fail_play;
    int fail_is_playing;
} FakeHost;

static FakeHost *g_fake;

static void fake_event(FakeHost *host, char op, uint32_t slot)
{
    if (host->event_count < 512) {
        host->events[host->event_count].op = op;
        host->events[host->event_count].slot = slot;
        ++host->event_count;
    }
}

static int fake_open(MacAudioMode mode, uint32_t rate, uint32_t channels,
                     MacAudioHost **host, char *error, size_t capacity)
{
    (void)error; (void)capacity;
    FakeHost *fake = calloc(1, sizeof(*fake));
    if (fake == NULL) return MAC_AUDIO_ERR_MEMORY;
    fake->mode = mode;
    fake->rate = rate;
    fake->channels = channels;
    fake->opens = 1;
    g_fake = fake;
    *host = (MacAudioHost *)fake;
    return MAC_AUDIO_OK;
}

static int fake_close(MacAudioHost *host, char *error, size_t capacity)
{
    (void)error; (void)capacity;
    FakeHost *fake = (FakeHost *)host;
    ++fake->closes;
    /* keep the struct alive for inspection; the harness frees it */
    return MAC_AUDIO_OK;
}

static int fake_play(MacAudioHost *host, uint32_t slot, const float *pcm,
                     uint64_t frames, uint32_t channels, uint32_t rate,
                     float gain, int loop, char *error, size_t capacity)
{
    FakeHost *fake = (FakeHost *)host;
    (void)error; (void)capacity;
    fake_event(fake, 'P', slot);
    if (fake->fail_play) return MAC_AUDIO_ERR_ENGINE;
    if (pcm == NULL || slot >= 64u || loop != 0) return MAC_AUDIO_ERR_ARGUMENT;
    /* touch the whole buffer so ASan checks the provider's allocation */
    volatile float sink = 0.0f;
    for (uint64_t i = 0; i < frames * channels; ++i) sink += pcm[i];
    (void)sink;
    fake->slots[slot].active = 1;
    ++fake->slots[slot].plays;
    fake->slots[slot].gain = gain;
    fake->slots[slot].frames = frames;
    fake->slots[slot].channels = channels;
    fake->slots[slot].rate = rate;
    return MAC_AUDIO_OK;
}

static int fake_stop(MacAudioHost *host, uint32_t slot, char *error,
                     size_t capacity)
{
    FakeHost *fake = (FakeHost *)host;
    (void)error; (void)capacity;
    fake_event(fake, 'S', slot);
    if (slot >= 64u) return MAC_AUDIO_ERR_ARGUMENT;
    fake->slots[slot].active = 0;
    ++fake->slots[slot].stops;
    return MAC_AUDIO_OK;
}

static int fake_set_gain(MacAudioHost *host, uint32_t slot, float gain,
                         char *error, size_t capacity)
{
    FakeHost *fake = (FakeHost *)host;
    (void)error; (void)capacity;
    fake_event(fake, 'G', slot);
    if (slot >= 64u) return MAC_AUDIO_ERR_ARGUMENT;
    ++fake->slots[slot].set_gains;
    fake->slots[slot].last_set_gain = gain;
    return MAC_AUDIO_OK;
}

static int fake_is_playing(MacAudioHost *host, uint32_t slot, int *playing,
                           char *error, size_t capacity)
{
    FakeHost *fake = (FakeHost *)host;
    (void)error; (void)capacity;
    fake_event(fake, 'Q', slot);
    if (fake->fail_is_playing) return MAC_AUDIO_ERR_ENGINE;
    if (slot >= 64u) return MAC_AUDIO_ERR_ARGUMENT;
    *playing = fake->slots[slot].active;
    return MAC_AUDIO_OK;
}

static int fake_render(MacAudioHost *host, uint32_t frames,
                       MacAudioRender *render, char *error, size_t capacity)
{
    FakeHost *fake = (FakeHost *)host;
    (void)error; (void)capacity;
    fake_event(fake, 'R', frames);
    ++fake->renders;
    if (fake->mode != MAC_AUDIO_MODE_OFFLINE) return MAC_AUDIO_ERR_MODE;
    render->sample_rate = fake->rate;
    render->channels = fake->channels;
    render->frame_count = frames;
    render->interleaved_pcm = calloc((size_t)frames * fake->channels, sizeof(float));
    return render->interleaved_pcm ? MAC_AUDIO_OK : MAC_AUDIO_ERR_MEMORY;
}

static void fake_render_destroy(MacAudioRender *render)
{
    free(render->interleaved_pcm);
    memset(render, 0, sizeof(*render));
}

static LiveAudioHostOps fake_ops(void)
{
    LiveAudioHostOps ops;
    ops.open = fake_open;
    ops.close = fake_close;
    ops.play = fake_play;
    ops.stop = fake_stop;
    ops.set_gain = fake_set_gain;
    ops.is_playing = fake_is_playing;
    ops.render_offline = fake_render;
    ops.render_destroy = fake_render_destroy;
    return ops;
}

static int fake_count(const FakeHost *fake, char op)
{
    int n = 0;
    for (int i = 0; i < fake->event_count; ++i)
        if (fake->events[i].op == op) ++n;
    return n;
}

/* The slot a channel's current sound plays in, as the provider reports it. */
static uint32_t slot_of(LiveAudio *audio, uint16_t channel)
{
    LiveAudioChannelInfo info;
    memset(&info, 0, sizeof(info));
    (void)live_audio_get_channel_info(audio, channel, &info);
    return info.host_slot;
}

static void fake_free(void)
{
    free(g_fake);
    g_fake = NULL;
}

/* ---- construction helpers --------------------------------------------- */
static ActionSoundAudioCommand make_command(const char *stem, uint16_t channel,
                                            uint8_t category, float first,
                                            float second, uint32_t control)
{
    ActionSoundAudioCommand command;
    memset(&command, 0, sizeof(command));
    snprintf(command.asset_stem, sizeof(command.asset_stem), "%s", stem);
    command.channel = channel;
    command.volume_category = category;
    command.control_word = control;
    command.first_gain = first;
    command.second_gain = second;
    command.first_percent = (int16_t)lroundf(first * 100.0f);
    command.second_percent = (int16_t)lroundf(second * 100.0f);
    return command;
}

static int create_fake(Ctx *ctx, LiveAudio **audio, MacAudioMode mode)
{
    LiveAudioHostOps ops = fake_ops();
    LiveAudioConfig config;
    char error[256] = "";
    int status;
    char dir[1024];

    snprintf(dir, sizeof(dir), "%s", ctx->fixture_dir);
    memset(&config, 0, sizeof(config));
    config.game_directory = dir;
    config.mode = mode;
    config.log = log_sink;
    config.host_ops = &ops;
    g_log_count = 0;
    status = live_audio_create(&config, audio, error, sizeof(error));
    CHECK(ctx, status == LIVE_AUDIO_OK, "create failed: %d %s", status, error);
    return status == LIVE_AUDIO_OK;
}

static int create_real(Ctx *ctx, LiveAudio **audio, const char *dir,
                       MacAudioMode mode, uint32_t rate, uint32_t channels)
{
    LiveAudioConfig config;
    char error[512] = "";
    int status;

    memset(&config, 0, sizeof(config));
    config.game_directory = dir;
    config.mode = mode;
    config.offline_sample_rate = rate;
    config.offline_channels = channels;
    config.log = log_sink;
    g_log_count = 0;
    status = live_audio_create(&config, audio, error, sizeof(error));
    if (status != LIVE_AUDIO_OK) {
        CHECK(ctx, 0, "real create failed: %d %s", status, error);
        return 0;
    }
    return 1;
}

static int playing(LiveAudio *audio, uint16_t channel)
{
    int still = -1;
    ActionSoundBackendStatus status = live_audio_is_playing(audio, channel, &still);
    return status == ACTION_SOUND_BACKEND_OK ? still : -1;
}

static void settle_ms(unsigned ms) { usleep(ms * 1000u); }

/* poll up to ~1 s for the asynchronous host completion callback */
static int wait_until_not_playing(LiveAudio *audio, uint16_t channel)
{
    for (int i = 0; i < 200; ++i) {
        if (playing(audio, channel) == 0) return 1;
        settle_ms(5);
    }
    return 0;
}

/* ---- tests: asset-name matching --------------------------------------- */
static void t_match_names(Ctx *ctx)
{
    const char *names[] = {"readme.txt", "Tone.HIS", "other.his", "tone.hisx",
                           "atone.his", "NAME.his"};
    size_t index = 99;
    CHECK(ctx, live_audio_match_asset_name("Tone", names, 6, &index) == LIVE_AUDIO_MATCH_ONE && index == 1u);
    CHECK(ctx, live_audio_match_asset_name("TONE", names, 6, &index) == LIVE_AUDIO_MATCH_ONE && index == 1u);
    CHECK(ctx, live_audio_match_asset_name("tOnE", names, 6, &index) == LIVE_AUDIO_MATCH_ONE && index == 1u);
    CHECK(ctx, live_audio_match_asset_name("name", names, 6, &index) == LIVE_AUDIO_MATCH_ONE && index == 5u);
    CHECK(ctx, live_audio_match_asset_name("missing", names, 6, &index) == LIVE_AUDIO_MATCH_NONE);
    CHECK(ctx, live_audio_match_asset_name("ton", names, 6, &index) == LIVE_AUDIO_MATCH_NONE);
    CHECK(ctx, live_audio_match_asset_name("", names, 6, &index) == LIVE_AUDIO_MATCH_NONE);
    CHECK(ctx, live_audio_match_asset_name("Tone", names, 0, &index) == LIVE_AUDIO_MATCH_NONE);
    {
        const char *dup[] = {"A.HIS", "x.his", "a.his"};
        CHECK(ctx, live_audio_match_asset_name("a", dup, 3, &index) == LIVE_AUDIO_MATCH_AMBIGUOUS);
        CHECK(ctx, live_audio_match_asset_name("x", dup, 3, &index) == LIVE_AUDIO_MATCH_ONE && index == 1u);
    }
    {
        /* exactly 32 stem characters is the longest the command can carry */
        char stem32[40], stem33[40], name32[48];
        const char *one[1];
        memset(stem32, 's', 32); stem32[32] = 0;
        memset(stem33, 's', 33); stem33[33] = 0;
        snprintf(name32, sizeof(name32), "%s.HIS", stem32);
        one[0] = name32;
        CHECK(ctx, live_audio_match_asset_name(stem32, one, 1, &index) == LIVE_AUDIO_MATCH_ONE);
        CHECK(ctx, live_audio_match_asset_name(stem33, one, 1, &index) == LIVE_AUDIO_MATCH_INVALID);
    }
    CHECK(ctx, live_audio_match_asset_name("a/b", names, 6, &index) == LIVE_AUDIO_MATCH_INVALID);
    CHECK(ctx, live_audio_match_asset_name("a\\b", names, 6, &index) == LIVE_AUDIO_MATCH_INVALID);
    CHECK(ctx, live_audio_match_asset_name(NULL, names, 6, &index) == LIVE_AUDIO_MATCH_INVALID);
    CHECK(ctx, live_audio_match_asset_name("Tone", NULL, 6, &index) == LIVE_AUDIO_MATCH_NONE);
}

/* ---- tests: load / lookup mapping -------------------------------------- */
static void t_lookup_and_status_mapping(Ctx *ctx)
{
    LiveAudio *audio = NULL;
    ActionSoundAudioCommand command;
    ActionSoundBackendStatus status;
    LiveAudioChannelInfo info;

    if (!create_fake(ctx, &audio, MAC_AUDIO_MODE_OUTPUT)) return;
    /* the file on disk is Tone.HIS; every ASCII case spelling resolves */
    command = make_command("tone", 0, 1, 1.0f, 1.0f, 0);
    CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_OK);
    command = make_command("TONE", 1, 1, 1.0f, 1.0f, 0);
    CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_OK);
    command = make_command("Tone", 2, 1, 1.0f, 1.0f, 0);
    CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_get_channel_info(audio, 0, &info) == LIVE_AUDIO_OK && info.loaded == 1u &&
          info.frame_count == TONE_FRAMES && info.channels == 2u && info.sample_rate == 48000u);

    /* missing asset: kernel advances without PlaySound */
    g_log_count = 0;
    command = make_command("NoSuchSound", 3, 1, 1.0f, 1.0f, 0);
    status = live_audio_load_sound(audio, &command);
    CHECK(ctx, status == ACTION_SOUND_BACKEND_NO_RESOURCE, "status=%d", status);
    CHECK(ctx, g_log_count >= 1 && log_contains("NoSuchSound"), "missing asset must be logged");
    CHECK(ctx, live_audio_get_channel_info(audio, 3, &info) == LIVE_AUDIO_OK && info.loaded == 0u);

    /* a directory named *.his is not an asset */
    command = make_command("DirNamed", 3, 1, 1.0f, 1.0f, 0);
    CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_NO_RESOURCE);

    /* empty stem cannot name a file */
    command = make_command("", 3, 1, 1.0f, 1.0f, 0);
    CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_NO_RESOURCE);

    /* corrupt / unsupported HIS payloads are a decode failure, not "missing" */
    {
        const char *bad[] = {"BadMagic", "Truncated", "ZeroBytes", "HugeDecl", "AllFF", "BadVersion"};
        for (size_t i = 0; i < sizeof(bad) / sizeof(bad[0]); ++i) {
            command = make_command(bad[i], 4, 1, 1.0f, 1.0f, 0);
            status = live_audio_load_sound(audio, &command);
            CHECK(ctx, status == ACTION_SOUND_BACKEND_ERROR, "%s -> %d", bad[i], status);
            CHECK(ctx, live_audio_get_channel_info(audio, 4, &info) == LIVE_AUDIO_OK && info.loaded == 0u);
        }
    }

    /* malformed commands never reach the filesystem */
    command = make_command("a/b", 3, 1, 1.0f, 1.0f, 0);
    CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_ERROR);
    command = make_command("a\\b", 3, 1, 1.0f, 1.0f, 0);
    CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_ERROR);
    {
        char long_stem[40];
        memset(long_stem, 't', 33); long_stem[33] = 0;
        command = make_command(long_stem, 3, 1, 1.0f, 1.0f, 0);
        CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_ERROR);
    }
    memset(&command, 0, sizeof(command));
    memset(command.asset_stem, 'x', sizeof(command.asset_stem)); /* no NUL */
    command.channel = 3; command.first_gain = command.second_gain = 1.0f;
    CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_ERROR);

    CHECK(ctx, live_audio_load_sound(audio, NULL) == ACTION_SOUND_BACKEND_ERROR);
    CHECK(ctx, live_audio_load_sound(NULL, &command) == ACTION_SOUND_BACKEND_ERROR);
    live_audio_destroy(audio);
    fake_free();
}

static void t_ambiguous_directory(Ctx *ctx)
{
    /* The fixture directory is only populated with two case variants when the
     * test volume is case-sensitive (the Python harness arranges that). */
    LiveAudio *audio = NULL;
    ActionSoundAudioCommand command = make_command("twin", 0, 1, 1.0f, 1.0f, 0);
    char path[1100];
    snprintf(path, sizeof(path), "%s/CDSound/TWIN.HIS", ctx->fixture_dir);
    if (access(path, F_OK) != 0) { ctx->skipped = 1; snprintf(ctx->detail, sizeof(ctx->detail), "no case-variant fixture"); return; }
    if (!create_fake(ctx, &audio, MAC_AUDIO_MODE_OUTPUT)) return;
    CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_ERROR);
    CHECK(ctx, log_contains("ambiguous"), "ambiguity must be logged");
    live_audio_destroy(audio);
    fake_free();
}

static void t_missing_sound_directory(Ctx *ctx)
{
    LiveAudio *audio = NULL;
    ActionSoundAudioCommand command = make_command("tone", 0, 1, 1.0f, 1.0f, 0);
    LiveAudioHostOps ops = fake_ops();
    LiveAudioConfig config;
    char error[128];
    memset(&config, 0, sizeof(config));
    config.game_directory = "/nonexistent-live-audio-dir";
    config.host_ops = &ops;
    config.log = log_sink;
    g_log_count = 0;
    CHECK(ctx, live_audio_create(&config, &audio, error, sizeof(error)) == LIVE_AUDIO_OK);
    if (audio == NULL) return;
    CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_NO_RESOURCE);
    live_audio_destroy(audio);
    fake_free();
}

/* ---- tests: channels ---------------------------------------------------- */
static void t_channel_bounds(Ctx *ctx)
{
    LiveAudio *audio = NULL;
    ActionSoundAudioCommand command;
    LiveAudioChannelInfo info;
    int still = 7;
    if (!create_fake(ctx, &audio, MAC_AUDIO_MODE_OUTPUT)) return;
    CHECK(ctx, LIVE_AUDIO_CHANNEL_COUNT == 32u);
    for (uint16_t ch = 0; ch < 32u; ++ch) {
        command = make_command("tone", ch, (uint8_t)(ch % 4u), 1.0f, 1.0f, 0);
        CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_OK, "ch %u", ch);
        CHECK(ctx, live_audio_play_sound(audio, ch) == ACTION_SOUND_BACKEND_OK, "ch %u", ch);
    }
    CHECK(ctx, g_fake->opens == 1);
    /* the 32 channels use 32 distinct host slots */
    {
        unsigned seen[64] = {0};
        for (uint16_t ch = 0; ch < 32u; ++ch) {
            uint32_t slot = slot_of(audio, ch);
            CHECK(ctx, slot < 64u && seen[slot] == 0u, "slot %u reused", slot);
            if (slot < 64u) seen[slot] = 1u;
        }
    }
    uint16_t bad[] = {32u, 33u, 255u, 65535u};
    for (size_t i = 0; i < sizeof(bad) / sizeof(bad[0]); ++i) {
        command = make_command("tone", bad[i], 0, 1.0f, 1.0f, 0);
        CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_ERROR);
        CHECK(ctx, live_audio_play_sound(audio, bad[i]) == ACTION_SOUND_BACKEND_ERROR);
        still = 7;
        CHECK(ctx, live_audio_is_playing(audio, bad[i], &still) == ACTION_SOUND_BACKEND_ERROR);
        CHECK(ctx, live_audio_unload_sound(audio, bad[i]) == ACTION_SOUND_BACKEND_ERROR);
        CHECK(ctx, live_audio_stop_channel(audio, bad[i]) != LIVE_AUDIO_OK);
        CHECK(ctx, live_audio_get_channel_info(audio, bad[i], &info) != LIVE_AUDIO_OK);
    }
    /* volume category outside the four-entry table is a malformed command */
    command = make_command("tone", 0, 4, 1.0f, 1.0f, 0);
    CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_ERROR);
    /* gains must be finite and within [0,1] */
    command = make_command("tone", 0, 0, 1.0f, 1.0f, 0);
    command.first_gain = NAN;
    CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_ERROR);
    command.first_gain = 1.5f;
    CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_ERROR);
    command.first_gain = 1.0f; command.second_gain = -0.25f;
    CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_ERROR);
    CHECK(ctx, live_audio_is_playing(audio, 0, NULL) == ACTION_SOUND_BACKEND_ERROR);
    live_audio_destroy(audio);
    fake_free();
}

static void t_play_before_load(Ctx *ctx)
{
    LiveAudio *audio = NULL;
    ActionSoundAudioCommand command = make_command("tone", 5, 1, 1.0f, 1.0f, 0);
    int still = 9;
    if (!create_fake(ctx, &audio, MAC_AUDIO_MODE_OUTPUT)) return;
    CHECK(ctx, live_audio_play_sound(audio, 5) == ACTION_SOUND_BACKEND_ERROR);
    CHECK(ctx, fake_count(g_fake, 'P') == 0, "host play must not be called");
    CHECK(ctx, live_audio_is_playing(audio, 5, &still) == ACTION_SOUND_BACKEND_OK && still == 0);
    /* after unload, play is an error again */
    CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_unload_sound(audio, 5) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_play_sound(audio, 5) == ACTION_SOUND_BACKEND_ERROR);
    CHECK(ctx, live_audio_unload_sound(audio, 5) == ACTION_SOUND_BACKEND_OK, "unload is idempotent");
    CHECK(ctx, fake_count(g_fake, 'P') == 0);
    /* a failed load leaves nothing to play either */
    command = make_command("NoSuchSound", 5, 1, 1.0f, 1.0f, 0);
    CHECK(ctx, live_audio_load_sound(audio, &command) == ACTION_SOUND_BACKEND_NO_RESOURCE);
    CHECK(ctx, live_audio_play_sound(audio, 5) == ACTION_SOUND_BACKEND_ERROR);
    live_audio_destroy(audio);
    fake_free();
}

static void t_reload_replaces(Ctx *ctx)
{
    LiveAudio *audio = NULL;
    ActionSoundAudioCommand a = make_command("tone", 7, 1, 1.0f, 1.0f, 0x11u);
    ActionSoundAudioCommand b = make_command("mono", 7, 2, 0.5f, 1.0f, 0x22u);
    ActionSoundAudioCommand missing = make_command("NoSuchSound", 7, 1, 1.0f, 1.0f, 0);
    LiveAudioChannelInfo before, after;
    if (!create_fake(ctx, &audio, MAC_AUDIO_MODE_OUTPUT)) return;
    CHECK(ctx, live_audio_load_sound(audio, &a) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_play_sound(audio, 7) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, playing(audio, 7) == 1);
    CHECK(ctx, live_audio_get_channel_info(audio, 7, &before) == LIVE_AUDIO_OK);
    CHECK(ctx, before.control_word == 0x11u && before.frame_count == TONE_FRAMES);
    CHECK(ctx, live_audio_load_sound(audio, &b) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_get_channel_info(audio, 7, &after) == LIVE_AUDIO_OK);
    CHECK(ctx, after.loaded == 1u && after.started == 0u && after.finished == 0u);
    CHECK(ctx, after.frame_count == MONO_FRAMES && after.channels == 2u && after.sample_rate == 22050u /* mono is duplicated to stereo */);
    CHECK(ctx, after.control_word == 0x22u && after.volume_category == 2u);
    CHECK(ctx, after.generation > before.generation);
    /* the replaced sound was stopped in its own slot, and is not audible */
    CHECK(ctx, g_fake->slots[before.host_slot].active == 0 && g_fake->slots[before.host_slot].stops >= 1);
    CHECK(ctx, playing(audio, 7) == 0, "reloaded but not yet played");
    CHECK(ctx, live_audio_play_sound(audio, 7) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, g_fake->slots[after.host_slot].active == 1 && g_fake->slots[after.host_slot].frames == MONO_FRAMES);
    CHECK(ctx, playing(audio, 7) == 1);
    /* a load that fails still replaces: the channel ends up empty, not stale */
    CHECK(ctx, live_audio_load_sound(audio, &missing) == ACTION_SOUND_BACKEND_NO_RESOURCE);
    CHECK(ctx, live_audio_get_channel_info(audio, 7, &after) == LIVE_AUDIO_OK && after.loaded == 0u);
    CHECK(ctx, playing(audio, 7) == 0);
    live_audio_destroy(audio);
    fake_free();
}

/* ---- tests: gain -------------------------------------------------------- */
static void t_gain_composition(Ctx *ctx)
{
    LiveAudio *audio = NULL;
    LiveAudioChannelInfo info;
    float scalar = -1.0f;
    ActionSoundAudioCommand c;
    if (!create_fake(ctx, &audio, MAC_AUDIO_MODE_OUTPUT)) return;
    for (uint8_t cat = 0; cat < 4u; ++cat) {
        CHECK(ctx, live_audio_get_category_scalar(audio, cat, &scalar) == LIVE_AUDIO_OK && scalar == 1.0f);
    }
    c = make_command("tone", 0, 1, 0.5f, 0.25f, 0xabcd1234u);
    CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_play_sound(audio, 0) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_get_channel_info(audio, 0, &info) == LIVE_AUDIO_OK);
    CHECK(ctx, info.first_gain == 0.5f && info.second_gain == 0.25f && info.category_scalar == 1.0f);
    CHECK(ctx, info.final_gain == 0.125f, "final=%g", info.final_gain);
    CHECK(ctx, g_fake->slots[info.host_slot].gain == 0.125f, "host gain=%g", g_fake->slots[info.host_slot].gain);
    CHECK(ctx, info.control_word == 0xabcd1234u && info.volume_category == 1u);

    /* the category scalar multiplies in, per category */
    CHECK(ctx, live_audio_set_category_scalar(audio, 1, 0.5f) == LIVE_AUDIO_OK);
    CHECK(ctx, live_audio_get_channel_info(audio, 0, &info) == LIVE_AUDIO_OK && info.final_gain == 0.0625f);
    /* a playing channel is re-gained on the host */
    CHECK(ctx, g_fake->slots[info.host_slot].last_set_gain == 0.0625f && g_fake->slots[info.host_slot].set_gains >= 1);
    c = make_command("tone", 1, 2, 0.5f, 0.25f, 0);
    CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_play_sound(audio, 1) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_get_channel_info(audio, 1, &info) == LIVE_AUDIO_OK && info.final_gain == 0.125f, "category 2 is untouched");
    c = make_command("tone", 2, 1, 0.5f, 0.25f, 0);
    CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_play_sound(audio, 2) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, g_fake->slots[slot_of(audio, 2)].gain == 0.0625f, "a later load uses the live table");

    /* non-power-of-two operands: same float expression, same order */
    c = make_command("tone", 3, 3, 0.3f, 0.7f, 0);
    CHECK(ctx, live_audio_set_category_scalar(audio, 3, 0.9f) == LIVE_AUDIO_OK);
    CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_get_channel_info(audio, 3, &info) == LIVE_AUDIO_OK);
    {
        volatile float expected = 0.3f * 0.7f;
        expected = expected * 0.9f;
        CHECK(ctx, info.final_gain == expected, "final=%.9g expected=%.9g", info.final_gain, expected);
    }
    /* gain zero and one are legal */
    c = make_command("tone", 4, 0, 0.0f, 1.0f, 0);
    CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_get_channel_info(audio, 4, &info) == LIVE_AUDIO_OK && info.final_gain == 0.0f);

    /* the informational S04-1 curve is reported, not applied */
    c = make_command("tone", 6, 0, 1.0f, 1.0f, 0);
    CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_get_channel_info(audio, 6, &info) == LIVE_AUDIO_OK);
    CHECK(ctx, info.reference_first_attenuation_valid == 1u && info.reference_first_attenuation == 0,
          "att=%d", info.reference_first_attenuation);
    c = make_command("tone", 6, 0, 0.5f, 1.0f, 0);
    CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_get_channel_info(audio, 6, &info) == LIVE_AUDIO_OK);
    {
        int32_t expected = 0;
        CHECK(ctx, sound_control_calculate_attenuation(0.5f, 1.0f, 0x027fu, &expected) == SOUND_CONTROL_OK);
        CHECK(ctx, info.reference_first_attenuation_valid == 1u && info.reference_first_attenuation == expected);
    }

    /* rejected scalars leave the table alone */
    CHECK(ctx, live_audio_set_category_scalar(audio, 0, NAN) != LIVE_AUDIO_OK);
    CHECK(ctx, live_audio_set_category_scalar(audio, 0, -0.1f) != LIVE_AUDIO_OK);
    CHECK(ctx, live_audio_set_category_scalar(audio, 0, 1.1f) != LIVE_AUDIO_OK);
    CHECK(ctx, live_audio_set_category_scalar(audio, 4, 0.5f) != LIVE_AUDIO_OK);
    CHECK(ctx, live_audio_get_category_scalar(audio, 0, &scalar) == LIVE_AUDIO_OK && scalar == 1.0f);
    CHECK(ctx, live_audio_get_category_scalar(audio, 4, &scalar) != LIVE_AUDIO_OK);
    live_audio_destroy(audio);
    fake_free();
}

/* ---- tests: playing state ----------------------------------------------- */
static void t_is_playing_lifecycle_fake(Ctx *ctx)
{
    LiveAudio *audio = NULL;
    ActionSoundAudioCommand c = make_command("tone", 9, 1, 1.0f, 1.0f, 0);
    LiveAudioChannelInfo info;
    int queries_before;
    if (!create_fake(ctx, &audio, MAC_AUDIO_MODE_OUTPUT)) return;
    CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, playing(audio, 9) == 0, "loaded but not played");
    CHECK(ctx, live_audio_play_sound(audio, 9) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_get_channel_info(audio, 9, &info) == LIVE_AUDIO_OK);
    for (int i = 0; i < 50; ++i) CHECK(ctx, playing(audio, 9) == 1, "poll %d", i);
    queries_before = fake_count(g_fake, 'Q');
    CHECK(ctx, playing(audio, 9) == 1);
    CHECK(ctx, fake_count(g_fake, 'Q') == queries_before + 1, "one host query per poll");
    CHECK(ctx, fake_count(g_fake, 'R') == 0, "polling must not render or drain");
    /* natural completion reported by the host */
    g_fake->slots[info.host_slot].active = 0;
    CHECK(ctx, playing(audio, 9) == 0);
    CHECK(ctx, live_audio_get_channel_info(audio, 9, &info) == LIVE_AUDIO_OK && info.finished == 1u && info.loaded == 1u);
    for (int i = 0; i < 5; ++i) CHECK(ctx, playing(audio, 9) == 0);
    /* completion is latched: a host that later re-reports the slot active
     * (for example a recycled slot) does not resurrect the finished sound */
    g_fake->slots[info.host_slot].active = 1;
    CHECK(ctx, playing(audio, 9) == 0);
    g_fake->slots[info.host_slot].active = 0;
    /* playing again restarts the lifecycle */
    CHECK(ctx, live_audio_play_sound(audio, 9) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, playing(audio, 9) == 1);
    /* host query failure surfaces as an error, not as completion */
    g_fake->fail_is_playing = 1;
    CHECK(ctx, playing(audio, 9) == -1);
    g_fake->fail_is_playing = 0;
    CHECK(ctx, playing(audio, 9) == 1);
    /* a host play failure is logged and advances like the original wrapper
     * (NO_RESOURCE); it leaves the channel loaded but not playing */
    g_fake->fail_play = 1;
    CHECK(ctx, live_audio_play_sound(audio, 9) == ACTION_SOUND_BACKEND_NO_RESOURCE);
    g_fake->fail_play = 0;
    CHECK(ctx, live_audio_get_channel_info(audio, 9, &info) == LIVE_AUDIO_OK && info.loaded == 1u && info.started == 0u);
    CHECK(ctx, playing(audio, 9) == 0);
    live_audio_destroy(audio);
    fake_free();
}

static void t_stop_and_unload_mid_play(Ctx *ctx)
{
    LiveAudio *audio = NULL;
    ActionSoundAudioCommand c = make_command("tone", 10, 1, 1.0f, 1.0f, 0);
    LiveAudioChannelInfo info;
    uint32_t slot;
    if (!create_fake(ctx, &audio, MAC_AUDIO_MODE_OUTPUT)) return;
    CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_play_sound(audio, 10) == ACTION_SOUND_BACKEND_OK);
    slot = slot_of(audio, 10);
    CHECK(ctx, playing(audio, 10) == 1);
    CHECK(ctx, live_audio_unload_sound(audio, 10) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, g_fake->slots[slot].active == 0 && g_fake->slots[slot].stops == 1);
    CHECK(ctx, playing(audio, 10) == 0);
    CHECK(ctx, live_audio_get_channel_info(audio, 10, &info) == LIVE_AUDIO_OK && info.loaded == 0u && info.frame_count == 0u);

    CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_play_sound(audio, 10) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, playing(audio, 10) == 1);
    CHECK(ctx, live_audio_stop_channel(audio, 10) == LIVE_AUDIO_OK);
    CHECK(ctx, playing(audio, 10) == 0);
    CHECK(ctx, live_audio_get_channel_info(audio, 10, &info) == LIVE_AUDIO_OK && info.loaded == 1u && info.started == 0u);
    CHECK(ctx, live_audio_play_sound(audio, 10) == ACTION_SOUND_BACKEND_OK, "stopped channel can restart");
    CHECK(ctx, playing(audio, 10) == 1);
    live_audio_destroy(audio);
    fake_free();
}

static void t_stale_completion(Ctx *ctx)
{
    /* A host that delivers a replaced sound's completion late and without a
     * generation check, modelled by clearing the old slot's active flag after
     * the new sound has started. The provider must keep the two sounds in
     * different host slots so the new sound is unaffected. */
    LiveAudio *audio = NULL;
    ActionSoundAudioCommand a = make_command("tone", 11, 1, 1.0f, 1.0f, 0);
    ActionSoundAudioCommand b = make_command("long", 11, 1, 1.0f, 1.0f, 0);
    LiveAudioChannelInfo info_a, info_b;
    if (!create_fake(ctx, &audio, MAC_AUDIO_MODE_OUTPUT)) return;
    CHECK(ctx, live_audio_load_sound(audio, &a) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_play_sound(audio, 11) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_get_channel_info(audio, 11, &info_a) == LIVE_AUDIO_OK);
    CHECK(ctx, live_audio_load_sound(audio, &b) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_play_sound(audio, 11) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_get_channel_info(audio, 11, &info_b) == LIVE_AUDIO_OK);
    CHECK(ctx, info_b.generation != info_a.generation);
    CHECK(ctx, info_b.host_slot != info_a.host_slot, "old and new sound share host slot %u", info_a.host_slot);
    CHECK(ctx, info_a.host_slot % 32u == 11u && info_b.host_slot % 32u == 11u);
    /* late completion of the replaced sound arrives */
    g_fake->slots[info_a.host_slot].active = 0;
    CHECK(ctx, playing(audio, 11) == 1, "stale completion marked the new sound complete");
    /* the same through unload then reload */
    CHECK(ctx, live_audio_unload_sound(audio, 11) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_load_sound(audio, &a) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_play_sound(audio, 11) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_get_channel_info(audio, 11, &info_a) == LIVE_AUDIO_OK);
    g_fake->slots[info_b.host_slot].active = 0; /* completion of the unloaded sound */
    CHECK(ctx, playing(audio, 11) == 1, "stale completion after unload marked the new sound complete");
    g_fake->slots[info_a.host_slot].active = 0; /* the real one */
    CHECK(ctx, playing(audio, 11) == 0);
    live_audio_destroy(audio);
    fake_free();
}

static void t_destroy_frees_everything(Ctx *ctx)
{
    LiveAudio *audio = NULL;
    FakeHost *fake;
    uint32_t slots[3];
    if (!create_fake(ctx, &audio, MAC_AUDIO_MODE_OUTPUT)) return;
    for (uint16_t ch = 0; ch < 3u; ++ch) {
        ActionSoundAudioCommand c = make_command("long", ch, 0, 1.0f, 1.0f, 0);
        CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK);
        CHECK(ctx, live_audio_play_sound(audio, ch) == ACTION_SOUND_BACKEND_OK);
        slots[ch] = slot_of(audio, ch);
    }
    {
        ActionSoundAudioCommand c = make_command("long", 20, 0, 1.0f, 1.0f, 0);
        CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK); /* loaded, never played */
    }
    fake = g_fake;
    CHECK(ctx, live_audio_destroy(audio) == LIVE_AUDIO_OK);
    for (int i = 0; i < 3; ++i) CHECK(ctx, fake->slots[slots[i]].active == 0);
    CHECK(ctx, fake->closes == 1, "host closed %d times", fake->closes);
    CHECK(ctx, live_audio_destroy(NULL) == LIVE_AUDIO_OK);
    fake_free();
}

static void t_bind_backend(Ctx *ctx)
{
    LiveAudio *audio = NULL;
    ActionSoundBackend backend;
    int sentinel = 0;
    if (!create_fake(ctx, &audio, MAC_AUDIO_MODE_OUTPUT)) return;
    memset(&backend, 0, sizeof(backend));
    backend.resolve_auto_text = (ActionSoundBackendStatus (*)(void *, const uint8_t *, size_t, const uint8_t **, size_t *))&sentinel;
    CHECK(ctx, live_audio_bind_backend(audio, &backend) == LIVE_AUDIO_OK);
    CHECK(ctx, backend.context == (void *)audio);
    CHECK(ctx, backend.load_sound == live_audio_load_sound && backend.play_sound == live_audio_play_sound);
    CHECK(ctx, backend.is_playing == live_audio_is_playing && backend.unload_sound == live_audio_unload_sound);
    CHECK(ctx, (void *)backend.resolve_auto_text == (void *)&sentinel, "caption callbacks must be untouched");
    CHECK(ctx, live_audio_bind_backend(audio, NULL) != LIVE_AUDIO_OK);
    CHECK(ctx, live_audio_bind_backend(NULL, &backend) != LIVE_AUDIO_OK);
    live_audio_destroy(audio);
    fake_free();
}

static void t_config_and_modes(Ctx *ctx)
{
    LiveAudio *audio = NULL;
    LiveAudioHostOps ops = fake_ops();
    LiveAudioConfig config;
    char error[256];
    uint32_t rate = 0, channels = 0;
    memset(&config, 0, sizeof(config));
    CHECK(ctx, live_audio_create(NULL, &audio, error, sizeof(error)) != LIVE_AUDIO_OK);
    CHECK(ctx, live_audio_create(&config, &audio, error, sizeof(error)) != LIVE_AUDIO_OK, "game_directory is required");
    config.game_directory = ctx->fixture_dir;
    config.host_ops = &ops;
    CHECK(ctx, live_audio_create(&config, NULL, error, sizeof(error)) != LIVE_AUDIO_OK);
    config.mode = (MacAudioMode)7;
    CHECK(ctx, live_audio_create(&config, &audio, error, sizeof(error)) != LIVE_AUDIO_OK && audio == NULL);
    config.mode = MAC_AUDIO_MODE_OFFLINE;
    config.offline_channels = 3;
    CHECK(ctx, live_audio_create(&config, &audio, error, sizeof(error)) != LIVE_AUDIO_OK && audio == NULL);
    fake_free();
    config.offline_channels = 0;
    CHECK(ctx, live_audio_create(&config, &audio, error, sizeof(error)) == LIVE_AUDIO_OK);
    CHECK(ctx, audio && live_audio_offline_format(audio, &rate, &channels) == LIVE_AUDIO_OK &&
          rate == LIVE_AUDIO_DEFAULT_OFFLINE_SAMPLE_RATE && channels == LIVE_AUDIO_DEFAULT_OFFLINE_CHANNELS);
    CHECK(ctx, g_fake && g_fake->mode == MAC_AUDIO_MODE_OFFLINE && g_fake->rate == 48000u);
    /* advancing an output-mode provider is a mode error */
    live_audio_destroy(audio);
    fake_free();
    config.mode = MAC_AUDIO_MODE_OUTPUT;
    CHECK(ctx, live_audio_create(&config, &audio, error, sizeof(error)) == LIVE_AUDIO_OK);
    CHECK(ctx, audio && live_audio_advance_offline(audio, 100, NULL, NULL, 0) == LIVE_AUDIO_ERR_MODE);
    CHECK(ctx, audio && live_audio_offline_format(audio, &rate, &channels) == LIVE_AUDIO_ERR_MODE);
    CHECK(ctx, fake_count(g_fake, 'R') == 0);
    live_audio_destroy(audio);
    fake_free();
}

static void t_advance_offline_splits_and_counts(Ctx *ctx)
{
    LiveAudio *audio = NULL;
    LiveAudioOfflineStats stats;
    float capture[16];
    if (!create_fake(ctx, &audio, MAC_AUDIO_MODE_OFFLINE)) return;
    {
        ActionSoundAudioCommand c = make_command("tone", 0, 1, 1.0f, 1.0f, 0);
        CHECK(ctx, live_audio_advance_offline(audio, 100, &stats, NULL, 0) == LIVE_AUDIO_OK && stats.frames == 100u);
        CHECK(ctx, g_fake->renders == 0, "advances before the first play never reach the host");
        CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK);
        CHECK(ctx, live_audio_play_sound(audio, 0) == ACTION_SOUND_BACKEND_OK);
    }
    memset(&stats, 0xee, sizeof(stats));
    CHECK(ctx, live_audio_advance_offline(audio, 10000, &stats, NULL, 0) == LIVE_AUDIO_OK);
    CHECK(ctx, stats.frames == 10000u && stats.nonfinite_samples == 0u && stats.peak == 0.0);
    CHECK(ctx, live_audio_offline_frames_rendered(audio) == 10100u);
    CHECK(ctx, g_fake->renders == 3, "10000 frames in 4096 chunks = 3 renders, got %d", g_fake->renders);
    CHECK(ctx, live_audio_advance_offline(audio, 0, &stats, NULL, 0) == LIVE_AUDIO_OK && stats.frames == 0u);
    CHECK(ctx, live_audio_advance_offline(audio, 5, NULL, capture, 4) == LIVE_AUDIO_OK, "capture capacity is a cap, not a requirement");
    CHECK(ctx, live_audio_advance_offline(audio, 5, NULL, NULL, 4) != LIVE_AUDIO_OK, "capacity without buffer");
    CHECK(ctx, live_audio_offline_frames_rendered(audio) == 10105u);
    live_audio_destroy(audio);
    fake_free();
}

typedef struct ThreadProbe { LiveAudio *audio; int load, play, poll, unload, advance; } ThreadProbe;

static void *thread_main(void *argument)
{
    ThreadProbe *probe = argument;
    ActionSoundAudioCommand c = make_command("tone", 12, 1, 1.0f, 1.0f, 0);
    int still = 0;
    probe->load = live_audio_load_sound(probe->audio, &c);
    probe->play = live_audio_play_sound(probe->audio, 12);
    probe->poll = live_audio_is_playing(probe->audio, 12, &still);
    probe->unload = live_audio_unload_sound(probe->audio, 12);
    probe->advance = live_audio_advance_offline(probe->audio, 10, NULL, NULL, 0);
    return NULL;
}

static void t_main_thread_only(Ctx *ctx)
{
    LiveAudio *audio = NULL;
    ThreadProbe probe;
    pthread_t thread;
    LiveAudioChannelInfo info;
    if (!create_fake(ctx, &audio, MAC_AUDIO_MODE_OFFLINE)) return;
    memset(&probe, 0, sizeof(probe));
    probe.audio = audio;
    CHECK(ctx, pthread_create(&thread, NULL, thread_main, &probe) == 0);
    pthread_join(thread, NULL);
    CHECK(ctx, probe.load == ACTION_SOUND_BACKEND_ERROR && probe.play == ACTION_SOUND_BACKEND_ERROR &&
          probe.poll == ACTION_SOUND_BACKEND_ERROR && probe.unload == ACTION_SOUND_BACKEND_ERROR);
    CHECK(ctx, probe.advance == LIVE_AUDIO_ERR_THREAD, "advance=%d", probe.advance);
    CHECK(ctx, g_fake->event_count == 0, "no host call from a non-main thread");
    CHECK(ctx, live_audio_get_channel_info(audio, 12, &info) == LIVE_AUDIO_OK && info.loaded == 0u);
    live_audio_destroy(audio);
    fake_free();
}

/* Bounded sweep of single-byte and truncation damage to a valid HIS header,
 * loaded through the provider into a scratch directory. Every outcome must
 * be OK or ERROR (a present file is never "missing"), never a crash. */
static void t_malformed_header_sweep(Ctx *ctx)
{
    char template_path[] = "/tmp/rt1-live-audio-sweep-XXXXXX";
    char sound_dir[256], file_path[300], source_path[1100];
    static unsigned char original[90000];
    size_t original_length;
    FILE *file;
    LiveAudio *audio = NULL;
    LiveAudioHostOps ops = fake_ops();
    LiveAudioConfig config;
    ActionSoundAudioCommand c = make_command("fuzz", 8, 1, 1.0f, 1.0f, 0);
    uint32_t state = 0x1badc0deu;
    unsigned accepted = 0, rejected = 0;
    char error[128];

    snprintf(source_path, sizeof(source_path), "%s/CDSound/Tone.HIS", ctx->fixture_dir);
    file = fopen(source_path, "rb");
    if (file == NULL) { CHECK(ctx, 0, "fixture Tone.HIS missing"); return; }
    original_length = fread(original, 1, sizeof(original), file);
    fclose(file);
    CHECK(ctx, original_length == 30u + TONE_FRAMES * 4u, "length %zu", original_length);
    if (original_length != 30u + TONE_FRAMES * 4u) return;
    if (mkdtemp(template_path) == NULL) { CHECK(ctx, 0, "mkdtemp"); return; }
    snprintf(sound_dir, sizeof(sound_dir), "%s/CDSound", template_path);
    if (mkdir(sound_dir, 0700) != 0) { CHECK(ctx, 0, "mkdir"); return; }
    snprintf(file_path, sizeof(file_path), "%s/fuzz.his", sound_dir);

    memset(&config, 0, sizeof(config));
    config.game_directory = template_path;
    config.host_ops = &ops;
    config.log = log_sink;
    if (live_audio_create(&config, &audio, error, sizeof(error)) != LIVE_AUDIO_OK) {
        CHECK(ctx, 0, "create: %s", error);
        return;
    }
    for (unsigned round = 0; round < 360u && !ctx->failed; ++round) {
        static unsigned char damaged[90000];
        size_t length = original_length;
        ActionSoundBackendStatus status;
        memcpy(damaged, original, original_length);
        state ^= state << 13; state ^= state >> 17; state ^= state << 5;
        if (round < 30u) {
            length = round;                          /* every truncation inside the header */
        } else if (round < 60u) {
            length = original_length - 1u - (round - 30u); /* short payloads */
        } else if (round < 330u) {
            damaged[state % 30u] = (unsigned char)(state >> 8);   /* header byte damage */
        } else {
            damaged[30u + state % (original_length - 30u)] = (unsigned char)(state >> 8); /* payload byte */
        }
        file = fopen(file_path, "wb");
        if (file == NULL) { CHECK(ctx, 0, "write"); break; }
        if (length > 0u) fwrite(damaged, 1, length, file);
        fclose(file);
        g_log_count = 0;
        status = live_audio_load_sound(audio, &c);
        CHECK(ctx, status == ACTION_SOUND_BACKEND_OK || status == ACTION_SOUND_BACKEND_ERROR,
              "round %u length %zu -> status %d", round, length, status);
        if (status == ACTION_SOUND_BACKEND_OK) {
            LiveAudioChannelInfo info;
            ++accepted;
            CHECK(ctx, live_audio_get_channel_info(audio, 8, &info) == LIVE_AUDIO_OK && info.loaded == 1u &&
                  info.frame_count > 0u && info.channels >= 1u && info.channels <= 2u);
            CHECK(ctx, live_audio_play_sound(audio, 8) == ACTION_SOUND_BACKEND_OK);
        } else {
            LiveAudioChannelInfo info;
            ++rejected;
            CHECK(ctx, live_audio_get_channel_info(audio, 8, &info) == LIVE_AUDIO_OK && info.loaded == 0u);
        }
    }
    CHECK(ctx, rejected >= 100u, "rejected %u accepted %u", rejected, accepted);
    snprintf(ctx->detail + strlen(ctx->detail), sizeof(ctx->detail) - strlen(ctx->detail),
             "accepted=%u rejected=%u", accepted, rejected);
    live_audio_destroy(audio);
    fake_free();
    (void)remove(file_path);
    (void)rmdir(sound_dir);
    (void)rmdir(template_path);
}

/* ---- tests against the real offline AVAudioEngine host ----------------- */
static void t_real_offline_lifecycle(Ctx *ctx)
{
    LiveAudio *audio = NULL;
    ActionSoundAudioCommand c = make_command("tone", 0, 1, 1.0f, 1.0f, 0);
    LiveAudioOfflineStats stats;
    uint64_t rendered = 0;
    int polls = 0, completed = 0;
    char dir[1024];
    snprintf(dir, sizeof(dir), "%s", ctx->fixture_dir);
    if (!create_real(ctx, &audio, dir, MAC_AUDIO_MODE_OFFLINE, 48000, 2)) return;
    CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, playing(audio, 0) == 0);
    CHECK(ctx, live_audio_play_sound(audio, 0) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, playing(audio, 0) == 1);
    /* a few thousand frames per poll; never complete before the last frame
     * of the sound has been rendered */
    while (rendered < 8u * TONE_FRAMES && !completed) {
        CHECK(ctx, live_audio_advance_offline(audio, 2500, &stats, NULL, 0) == LIVE_AUDIO_OK);
        CHECK(ctx, stats.frames == 2500u && stats.nonfinite_samples == 0u);
        rendered += 2500u;
        ++polls;
        int p = playing(audio, 0);
        if (rendered < TONE_FRAMES) {
            CHECK(ctx, p == 1, "early completion after %llu of %u frames", (unsigned long long)rendered, TONE_FRAMES);
        } else if (p == 0) {
            completed = 1;
        } else if (rendered >= TONE_FRAMES + 3u * 2500u) {
            /* the completion callback is asynchronous; give it time */
            completed = wait_until_not_playing(audio, 0);
            break;
        }
        if (ctx->failed) break;
    }
    CHECK(ctx, completed, "sound never completed after %llu frames", (unsigned long long)rendered);
    CHECK(ctx, rendered >= TONE_FRAMES && rendered < TONE_FRAMES + 8u * 2500u, "completed at %llu", (unsigned long long)rendered);
    CHECK(ctx, polls >= 8, "polls=%d", polls);
    CHECK(ctx, playing(audio, 0) == 0);
    CHECK(ctx, live_audio_offline_frames_rendered(audio) == rendered);
    CHECK(ctx, live_audio_destroy(audio) == LIVE_AUDIO_OK);
}

static void t_real_offline_advance_before_any_play(Ctx *ctx)
{
    LiveAudio *audio = NULL;
    LiveAudioOfflineStats stats;
    float capture[16];
    char dir[1024];
    snprintf(dir, sizeof(dir), "%s", ctx->fixture_dir);
    if (!create_real(ctx, &audio, dir, MAC_AUDIO_MODE_OFFLINE, 48000, 2)) return;
    /* AVAudioEngine faults when rendered with no player node attached; the
     * provider must treat advances before the first play as virtual */
    memset(capture, 0x7f, sizeof(capture));
    CHECK(ctx, live_audio_advance_offline(audio, 4096, &stats, capture, 8) == LIVE_AUDIO_OK);
    CHECK(ctx, stats.frames == 4096u && stats.nonzero_samples == 0u && capture[0] == 0.0f);
    CHECK(ctx, live_audio_offline_frames_rendered(audio) == 4096u);
    CHECK(ctx, live_audio_unload_all(audio) == LIVE_AUDIO_OK);
    CHECK(ctx, live_audio_destroy(audio) == LIVE_AUDIO_OK);
}

static void t_real_offline_completion_is_deterministic(Ctx *ctx)
{
    /* completion must land on the same tick every run, not whenever the host
     * callback thread gets scheduled */
    for (int run = 0; run < 6 && !ctx->failed; ++run) {
        LiveAudio *audio = NULL;
        ActionSoundAudioCommand c = make_command("tone", 0, 1, 1.0f, 1.0f, 0);
        uint64_t rendered = 0;
        int completed_tick = -1;
        char dir[1024];
        snprintf(dir, sizeof(dir), "%s", ctx->fixture_dir);
        if (!create_real(ctx, &audio, dir, MAC_AUDIO_MODE_OFFLINE, 48000, 2)) return;
        CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK);
        CHECK(ctx, live_audio_play_sound(audio, 0) == ACTION_SOUND_BACKEND_OK);
        for (int tick = 0; tick < 40 && completed_tick < 0; ++tick) {
            CHECK(ctx, live_audio_advance_offline(audio, 2500, NULL, NULL, 0) == LIVE_AUDIO_OK);
            rendered += 2500u;
            if (playing(audio, 0) == 0) completed_tick = tick;
        }
        CHECK(ctx, completed_tick >= 0 && rendered >= TONE_FRAMES);
        /* tone is 20000 frames at the render rate: the 8th advance covers it */
        CHECK(ctx, completed_tick == 7, "run %d completed at tick %d", run, completed_tick);
        CHECK(ctx, live_audio_unload_all(audio) == LIVE_AUDIO_OK);
        CHECK(ctx, live_audio_destroy(audio) == LIVE_AUDIO_OK);
    }
}

static void t_real_offline_gain_composition(Ctx *ctx)
{
    LiveAudio *audio = NULL;
    ActionSoundAudioCommand c = make_command("long", 0, 2, 0.5f, 0.5f, 0);
    LiveAudioOfflineStats stats;
    char dir[1024];
    snprintf(dir, sizeof(dir), "%s", ctx->fixture_dir);
    if (!create_real(ctx, &audio, dir, MAC_AUDIO_MODE_OFFLINE, 48000, 2)) return;
    CHECK(ctx, live_audio_set_category_scalar(audio, 2, 0.5f) == LIVE_AUDIO_OK);
    CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_play_sound(audio, 0) == ACTION_SOUND_BACKEND_OK);
    /* the fixture is a +-0.5 square wave, so the peak is 0.5 * gain = 0.0625 */
    double peak = 0.0;
    for (int i = 0; i < 6; ++i) {
        CHECK(ctx, live_audio_advance_offline(audio, 4096, &stats, NULL, 0) == LIVE_AUDIO_OK);
        if (stats.peak > peak) peak = stats.peak;
    }
    CHECK(ctx, fabs(peak - 0.0625) < 1e-3, "peak=%g", peak);
    /* changing the category scalar while playing re-gains the live channel */
    CHECK(ctx, live_audio_set_category_scalar(audio, 2, 1.0f) == LIVE_AUDIO_OK);
    CHECK(ctx, live_audio_advance_offline(audio, 2048, &stats, NULL, 0) == LIVE_AUDIO_OK); /* settle */
    CHECK(ctx, live_audio_advance_offline(audio, 4096, &stats, NULL, 0) == LIVE_AUDIO_OK);
    peak = stats.peak;
    CHECK(ctx, fabs(peak - 0.125) < 1e-3, "peak=%g", peak);
    live_audio_destroy(audio);
}

static void t_real_offline_stop_and_unload(Ctx *ctx)
{
    LiveAudio *audio = NULL;
    ActionSoundAudioCommand c = make_command("long", 0, 0, 1.0f, 1.0f, 0);
    LiveAudioOfflineStats stats;
    char dir[1024];
    snprintf(dir, sizeof(dir), "%s", ctx->fixture_dir);
    if (!create_real(ctx, &audio, dir, MAC_AUDIO_MODE_OFFLINE, 48000, 2)) return;
    CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_play_sound(audio, 0) == ACTION_SOUND_BACKEND_OK);
    for (int i = 0; i < 3; ++i) CHECK(ctx, live_audio_advance_offline(audio, 2500, &stats, NULL, 0) == LIVE_AUDIO_OK);
    CHECK(ctx, playing(audio, 0) == 1);
    CHECK(ctx, live_audio_unload_sound(audio, 0) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, playing(audio, 0) == 0);
    CHECK(ctx, live_audio_advance_offline(audio, 4096, &stats, NULL, 0) == LIVE_AUDIO_OK);
    CHECK(ctx, live_audio_advance_offline(audio, 4096, &stats, NULL, 0) == LIVE_AUDIO_OK);
    CHECK(ctx, stats.peak < 1e-6, "audible after unload: peak=%g", stats.peak);
    settle_ms(100);
    CHECK(ctx, playing(audio, 0) == 0);
    /* stop keeps the sound loaded and replay plays again (the host takes up to
     * one render chunk to start contributing a freshly started player) */
    CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_play_sound(audio, 0) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_advance_offline(audio, 2500, &stats, NULL, 0) == LIVE_AUDIO_OK);
    CHECK(ctx, live_audio_stop_channel(audio, 0) == LIVE_AUDIO_OK);
    CHECK(ctx, playing(audio, 0) == 0);
    CHECK(ctx, live_audio_advance_offline(audio, 4096, &stats, NULL, 0) == LIVE_AUDIO_OK);
    CHECK(ctx, stats.peak < 1e-6, "audible after stop: peak=%g", stats.peak);
    CHECK(ctx, live_audio_play_sound(audio, 0) == ACTION_SOUND_BACKEND_OK);
    {
        double restart_peak = 0.0;
        for (int i = 0; i < 4; ++i) {
            CHECK(ctx, live_audio_advance_offline(audio, 4096, &stats, NULL, 0) == LIVE_AUDIO_OK);
            if (stats.peak > restart_peak) restart_peak = stats.peak;
        }
        CHECK(ctx, restart_peak > 0.4, "no audio after restart: peak=%g", restart_peak);
    }
    CHECK(ctx, playing(audio, 0) == 1);
    live_audio_destroy(audio);
}

static void t_real_offline_stale_completion_after_reload(Ctx *ctx)
{
    LiveAudio *audio = NULL;
    ActionSoundAudioCommand a = make_command("tone", 3, 1, 1.0f, 1.0f, 0);   /* 20000 frames */
    ActionSoundAudioCommand b = make_command("long", 3, 1, 1.0f, 1.0f, 0);   /* 60000 frames */
    LiveAudioOfflineStats stats;
    char dir[1024];
    snprintf(dir, sizeof(dir), "%s", ctx->fixture_dir);
    if (!create_real(ctx, &audio, dir, MAC_AUDIO_MODE_OFFLINE, 48000, 2)) return;
    CHECK(ctx, live_audio_load_sound(audio, &a) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_play_sound(audio, 3) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_advance_offline(audio, 5000, &stats, NULL, 0) == LIVE_AUDIO_OK);
    CHECK(ctx, playing(audio, 3) == 1);
    /* replace the sound while the first is mid-play */
    CHECK(ctx, live_audio_load_sound(audio, &b) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_play_sound(audio, 3) == ACTION_SOUND_BACKEND_OK);
    /* render past where the replaced sound would have finished (15000 more
     * frames) but well short of the new one (60000) */
    for (int i = 0; i < 8; ++i) CHECK(ctx, live_audio_advance_offline(audio, 4096, &stats, NULL, 0) == LIVE_AUDIO_OK);
    settle_ms(150); /* let any stale completion callback arrive */
    CHECK(ctx, playing(audio, 3) == 1, "stale completion ended the replacement");
    /* the replacement then completes after its own 60000 frames */
    uint64_t since_start = 8u * 4096u;
    int done = 0;
    while (since_start < 60000u + 6u * 4096u && !done) {
        CHECK(ctx, live_audio_advance_offline(audio, 4096, &stats, NULL, 0) == LIVE_AUDIO_OK);
        since_start += 4096u;
        int p = playing(audio, 3);
        if (since_start < 60000u) CHECK(ctx, p == 1, "early completion at %llu", (unsigned long long)since_start);
        if (p == 0) done = 1;
        if (ctx->failed) break;
    }
    if (!done) done = wait_until_not_playing(audio, 3);
    CHECK(ctx, done && since_start >= 60000u, "done=%d since_start=%llu", done, (unsigned long long)since_start);
    live_audio_destroy(audio);
}

/* The real shipped asset. */
static void t_end_to_end_nsht01(Ctx *ctx)
{
    char path[2048];
    char error[512] = "";
    HisAudio decoded = HIS_AUDIO_INIT;
    LiveAudio *audio = NULL;
    ActionSoundAudioCommand c = make_command("NSHT01", 5, 1, 1.0f, 1.0f, 0);
    LiveAudioOfflineStats stats;
    float *capture = NULL;
    uint64_t capacity, rendered = 0;
    int completed = 0;
    uint32_t rate = 0, channels = 0;
    LiveAudioChannelInfo info;
    uint64_t compared = 0, mismatched = 0, offset = 0;
    double scale = 0.0;

    if (ctx->game_dir == NULL || strcmp(ctx->game_dir, "-") == 0) {
        ctx->skipped = 1; snprintf(ctx->detail, sizeof(ctx->detail), "owner install not provided");
        return;
    }
    snprintf(path, sizeof(path), "%s/CDSound/NSHT01.HIS", ctx->game_dir);
    if (access(path, R_OK) != 0) {
        snprintf(path, sizeof(path), "%s/CDSound/NSHT01.his", ctx->game_dir);
        if (access(path, R_OK) != 0) {
            ctx->skipped = 1; snprintf(ctx->detail, sizeof(ctx->detail), "NSHT01 absent");
            return;
        }
    }
    if (his_audio_decode_file(path, &decoded, error, sizeof(error)) != HIS_AUDIO_OK) {
        CHECK(ctx, 0, "reference decode failed: %s", error);
        return;
    }
    rate = decoded.sample_rate;
    channels = decoded.channels;
    capacity = decoded.frame_count + 4u * LIVE_AUDIO_RENDER_CHUNK_FRAMES;
    capture = calloc((size_t)(capacity * 2u), sizeof(float));
    if (capture == NULL) { his_audio_destroy(&decoded); CHECK(ctx, 0, "capture alloc"); return; }
    if (!create_real(ctx, &audio, ctx->game_dir, MAC_AUDIO_MODE_OFFLINE, rate, 2)) goto done;

    CHECK(ctx, live_audio_load_sound(audio, &c) == ACTION_SOUND_BACKEND_OK);
    CHECK(ctx, live_audio_get_channel_info(audio, 5, &info) == LIVE_AUDIO_OK);
    CHECK(ctx, info.frame_count == decoded.frame_count && info.sample_rate == rate && info.channels == (channels == 1u ? 2u : channels),
          "frames %llu vs %llu", (unsigned long long)info.frame_count, (unsigned long long)decoded.frame_count);
    CHECK(ctx, live_audio_play_sound(audio, 5) == ACTION_SOUND_BACKEND_OK);
    double squares = 0.0, peak = 0.0;
    uint64_t nonfinite = 0, nonzero = 0;
    const uint64_t tick = 4096;
    uint64_t in_capture = 0;
    while (rendered < decoded.frame_count + 40u * tick && !completed) {
        CHECK(ctx, live_audio_advance_offline(audio, tick, &stats, capture + in_capture * 2u,
                                              capacity > in_capture ? capacity - in_capture : 0) == LIVE_AUDIO_OK);
        in_capture += stats.frames;
        rendered += stats.frames;
        squares += stats.sum_squares; nonfinite += stats.nonfinite_samples; nonzero += stats.nonzero_samples;
        if (stats.peak > peak) peak = stats.peak;
        int p = playing(audio, 5);
        if (rendered < decoded.frame_count) CHECK(ctx, p == 1, "early completion at %llu/%llu",
                                                  (unsigned long long)rendered, (unsigned long long)decoded.frame_count);
        else if (p == 0) completed = 1;
        if (ctx->failed) break;
    }
    if (!completed) completed = wait_until_not_playing(audio, 5);
    CHECK(ctx, completed, "NSHT01 did not complete");
    CHECK(ctx, rendered >= decoded.frame_count && rendered < decoded.frame_count + tick + 1u,
          "completion observed after %llu frames, decoded %llu", (unsigned long long)rendered,
          (unsigned long long)decoded.frame_count);
    CHECK(ctx, nonfinite == 0u, "nonfinite=%llu", (unsigned long long)nonfinite);
    CHECK(ctx, nonzero > 0u && peak > 1e-4 && squares > 0.0, "silent: peak=%g", peak);
    /* Sample comparison against the decoded PCM. The render format is stereo;
     * a mono source is mixed by the host, so its left/right relation and
     * scale are characterised (and required to be self-consistent) rather
     * than assumed. The host may start a fresh player a moment late, so the
     * sound is aligned at its first non-zero frame. */
    {
        const float *src = decoded.interleaved_pcm;
        uint64_t src_first = decoded.frame_count, cap_first = capacity, cap_last = 0u, frame;
        double dot = 0.0, norm = 0.0, worst_lr = 0.0;
        for (frame = 0; frame < decoded.frame_count; ++frame) {
            int any = 0;
            for (uint32_t k = 0; k < channels; ++k) any |= src[frame * channels + k] != 0.0f;
            if (any) { src_first = frame; break; }
        }
        for (frame = 0; frame < capacity; ++frame) {
            if (capture[frame * 2u] != 0.0f || capture[frame * 2u + 1u] != 0.0f) {
                if (cap_first == capacity) cap_first = frame;
                cap_last = frame;
            }
        }
        CHECK(ctx, cap_first != capacity && src_first != decoded.frame_count, "no audible frame");
        CHECK(ctx, cap_first >= src_first, "audio began early");
        offset = cap_first - src_first;
        CHECK(ctx, offset < 2u * tick, "start offset %llu frames", (unsigned long long)offset);
        CHECK(ctx, cap_last < decoded.frame_count + offset, "audio rendered past the decoded length");
        for (frame = src_first; frame < decoded.frame_count && frame + offset < capacity; ++frame)
            for (uint32_t k = 0; k < 2u; ++k) {
                float reference = src[frame * channels + (channels == 2u ? k : 0u)];
                dot += (double)capture[(frame + offset) * 2u + k] * reference;
                norm += (double)reference * reference;
            }
        scale = norm > 0.0 ? dot / norm : 0.0;
        for (frame = src_first; frame < decoded.frame_count && frame + offset < capacity; ++frame)
            for (uint32_t k = 0; k < 2u; ++k) {
                float reference = src[frame * channels + (channels == 2u ? k : 0u)];
                ++compared;
                if (fabs((double)capture[(frame + offset) * 2u + k] - scale * (double)reference) > 1e-3) ++mismatched;
            }
        for (frame = 0; frame < capacity; ++frame) {
            double d = fabs((double)capture[frame * 2u] - (double)capture[frame * 2u + 1u]);
            if (d > worst_lr) worst_lr = d;
        }
        CHECK(ctx, mismatched == 0u, "%llu of %llu samples differ from scale*decoded (scale=%.6f)",
              (unsigned long long)mismatched, (unsigned long long)compared, scale);
        CHECK(ctx, channels == 2u || worst_lr < 1e-6, "mono source rendered unequal left/right: %g", worst_lr);
        CHECK(ctx, scale > 0.999 && scale <= 1.0001, "host scale %.6f (mono is duplicated to stereo, unity)", scale);
    }
    snprintf(ctx->detail, sizeof(ctx->detail),
             "decoded_frames=%llu rate=%u src_channels=%u rendered_at_completion=%llu peak=%.6f nonzero=%llu compared=%llu mismatched=%llu start_offset=%llu host_scale=%.6f",
             (unsigned long long)decoded.frame_count, rate, channels, (unsigned long long)rendered, peak,
             (unsigned long long)nonzero, (unsigned long long)compared, (unsigned long long)mismatched,
             (unsigned long long)offset, scale);
done:
    live_audio_destroy(audio);
    free(capture);
    his_audio_destroy(&decoded);
}

/* ---- output-mode smoke (real device path; opt-in subcommand) ------------ */
static int smoke(const char *game_dir)
{
    LiveAudio *audio = NULL;
    Ctx ctx;
    ActionSoundAudioCommand c = make_command("NSHT01", 0, 1, 0.05f, 1.0f, 0);
    memset(&ctx, 0, sizeof(ctx));
    if (!create_real(&ctx, &audio, game_dir, MAC_AUDIO_MODE_OUTPUT, 0, 0)) { printf("SMOKE create FAIL %s\n", ctx.detail); return 1; }
    int ok = 1;
    ActionSoundBackendStatus s;
    s = live_audio_load_sound(audio, &c); printf("SMOKE load status=%d\n", s); ok &= (s == ACTION_SOUND_BACKEND_OK);
    s = live_audio_play_sound(audio, 0); printf("SMOKE play status=%d\n", s); ok &= (s == ACTION_SOUND_BACKEND_OK);
    int p = playing(audio, 0); printf("SMOKE playing_immediately=%d\n", p);
    ok &= (p == 1);
    settle_ms(300);
    p = playing(audio, 0); printf("SMOKE playing_after_300ms=%d\n", p);
    ok &= (p == 1);
    s = live_audio_unload_sound(audio, 0); printf("SMOKE unload status=%d\n", s); ok &= (s == ACTION_SOUND_BACKEND_OK);
    p = playing(audio, 0); printf("SMOKE playing_after_unload=%d\n", p); ok &= (p == 0);
    printf("SMOKE destroy status=%d\n", live_audio_destroy(audio));
    for (int i = 0; i < g_log_count; ++i) printf("SMOKE log: %s\n", g_log[i]);
    printf("SMOKE %s\n", ok ? "PASS" : "FAIL");
    return ok ? 0 : 1;
}

/* ---- registry ----------------------------------------------------------- */
typedef struct TestCase { const char *name; void (*run)(Ctx *); } TestCase;

static const TestCase tests[] = {
    {"match_names", t_match_names},
    {"lookup_and_status_mapping", t_lookup_and_status_mapping},
    {"ambiguous_directory", t_ambiguous_directory},
    {"missing_sound_directory", t_missing_sound_directory},
    {"channel_bounds", t_channel_bounds},
    {"play_before_load", t_play_before_load},
    {"reload_replaces", t_reload_replaces},
    {"gain_composition", t_gain_composition},
    {"is_playing_lifecycle_fake", t_is_playing_lifecycle_fake},
    {"stop_and_unload_mid_play", t_stop_and_unload_mid_play},
    {"stale_completion", t_stale_completion},
    {"destroy_frees_everything", t_destroy_frees_everything},
    {"bind_backend", t_bind_backend},
    {"config_and_modes", t_config_and_modes},
    {"advance_offline_splits_and_counts", t_advance_offline_splits_and_counts},
    {"main_thread_only", t_main_thread_only},
    {"malformed_header_sweep", t_malformed_header_sweep},
    {"real_offline_lifecycle", t_real_offline_lifecycle},
    {"real_offline_advance_before_any_play", t_real_offline_advance_before_any_play},
    {"real_offline_completion_is_deterministic", t_real_offline_completion_is_deterministic},
    {"real_offline_gain_composition", t_real_offline_gain_composition},
    {"real_offline_stop_and_unload", t_real_offline_stop_and_unload},
    {"real_offline_stale_completion_after_reload", t_real_offline_stale_completion_after_reload},
    {"end_to_end_nsht01", t_end_to_end_nsht01},
};

int main(int argc, char **argv)
{
    int failures = 0;
    const size_t count = sizeof(tests) / sizeof(tests[0]);
    if (argc < 3) { fprintf(stderr, "usage: %s <fixture_dir> <game_dir|-> [list|smoke|test...]\n", argv[0]); return 2; }
    if (argc >= 4 && strcmp(argv[3], "list") == 0) {
        for (size_t i = 0; i < count; ++i) printf("%s\n", tests[i].name);
        return 0;
    }
    if (argc >= 4 && strcmp(argv[3], "smoke") == 0) return smoke(argv[1]);
    for (size_t i = 0; i < count; ++i) {
        int selected = argc < 4;
        for (int a = 3; a < argc && !selected; ++a) selected = strcmp(argv[a], tests[i].name) == 0;
        if (!selected) continue;
        Ctx ctx;
        memset(&ctx, 0, sizeof(ctx));
        ctx.fixture_dir = argv[1];
        ctx.game_dir = argv[2];
        tests[i].run(&ctx);
        printf("TEST %s %s %s\n", tests[i].name, ctx.failed ? "FAIL" : (ctx.skipped ? "SKIP" : "PASS"), ctx.detail);
        fflush(stdout);
        if (ctx.failed) ++failures;
    }
    return failures == 0 ? 0 : 1;
}
